document.getElementById('exMonth').addEventListener('change', function () {
  const year = document.getElementById('exYear').value;
  const month = this.value;
  fetch(`nifty-hoc/nifty-whoc-filters.php?type=expiryDate&year=${year}&month=${month}`)
    .then(res => res.json())
    .then(expiries => {
