document.getElementById('exExpiry').addEventListener('change', function () {
  const expiry = this.value;
  fetch(`nifty-hoc/nifty-whoc-filters.php?type=date&expiry=${expiry}`)
    .then(res => res.json())
    .then(dates => {
      const dateDropdown = document.getElementById('exDate');
      dateDropdown.disabled = false;
      dateDropdown.innerHTML = '<option value="">Select Date</option>';
      dates.forEach(date => {
        dateDropdown.innerHTML += `<option value="${date}">${date}</option>`;
