document.getElementById('exDate').addEventListener('change', function () {
  const expiry = document.getElementById('exExpiry').value;
  const date = this.value;
  if (expiry && date) {
    fetchData(expiry, date);
  }
});

document.getElementById('atmRange').addEventListener('change', function () {
  selectedATM = this.value;
  applyATMFilter();
});

function fetchData(expiry, date) {
  fetch(`nifty-hoc/nifty-whoc-data.php?expiry=${expiry}&date=${date}`)
    .then(res => res.json())
    .then(json => {
      fullData = Array.isArray(json.data) ? json.data : [];
      applyATMFilter();
    });
}

function applyATMFilter() {
  let filtered = fullData;
  const range = parseInt(selectedATM);
  if (!isNaN(range)) {
    filtered = fullData.filter(r => Math.abs(parseInt(r.ATM)) <= range);
  }

  if (!filtered || filtered.length === 0) {
    if (dataTable) dataTable.clear().draw();
    clearCharts();
    document.getElementById("maxPainDisplay").innerText = `Max Pain: N/A`;
    return;
  }

  if (dataTable) {
  dataTable.clear().rows.add(filtered).draw();
} else {
  dataTable = $('#hocTable').DataTable({
    data: filtered,
    columns: [
      { data: 'Turnover' },
      { data: 'Volume' },
      { data: 'OI' },
      { data: 'OI_Change' },
      { data: 'Close' },
      { data: 'Strike' },
      { data: 'PE_Close' },
      { data: 'PE_OI_Change' },
      { data: 'PE_OI' },
      { data: 'PE_Volume' },
      { data: 'PE_Turnover' },
      { data: 'Spot' },
      {
        data: 'PCR',
        render: function (data) {
          const color = data >= 1 ? 'green' : 'red';
          return `<span style="color: ${color}; font-weight: bold;">${data}</span>`;
        }
      }
    ],
    scrollX: true,
    fixedHeader: true,
    pageLength: 100,
    searching: false,
    ordering: false,

    // ✅ Highlight ATM rows where ATM === 0
    rowCallback: function (row, data) {
      if (parseInt(data.ATM) === 0) {
        $(row).css('background-color', '#fdf2e9'); // Optional: .addClass('atm-highlight');
      }
    }
  });
}

// ✅ Update footer, style, and charts
calculateFooterSums(filtered);
styleTableRows(filtered);
updateCharts(filtered);

}

function calculateFooterSums(data) {
  let ceOi = 0, ceOiChange = 0, peOi = 0, peOiChange = 0;
  data.forEach(row => {
    ceOi += parseFloat(row.OI || 0);
    ceOiChange += parseFloat(row.OI_Change || 0);
    peOi += parseFloat(row.PE_OI || 0);
    peOiChange += parseFloat(row.PE_OI_Change || 0);
  });
  document.getElementById('ceOiSum').textContent = ceOi.toLocaleString();
  document.getElementById('ceOiChangeSum').textContent = ceOiChange.toLocaleString();
  document.getElementById('peOiSum').textContent = peOi.toLocaleString();
  document.getElementById('peOiChangeSum').textContent = peOiChange.toLocaleString();
  return { ceOi, ceOiChange, peOi, peOiChange };
}

function styleTableRows(data) {
  setTimeout(() => {
    $('#hocTable tbody tr').each(function (index) {
      const row = data[index];

      // Highlight negative OI Change
      const oiChange = parseFloat(row.OI_Change || 0);
      const peOiChange = parseFloat(row.PE_OI_Change || 0);
      if (oiChange < 0) $(this).find('td:eq(3)').addClass('oi-change-red');  // OI_Change
      if (peOiChange < 0) $(this).find('td:eq(7)').addClass('oi-change-red'); // PE_OI_Change
    });

    // Highlight top 3 OI and PE OI
    const topOI = [...data].map(r => parseInt(r.OI)).filter(Boolean).sort((a, b) => b - a).slice(0, 3);
    const topPEOI = [...data].map(r => parseInt(r.PE_OI)).filter(Boolean).sort((a, b) => b - a).slice(0, 3);

    $('#hocTable tbody tr').each(function (index) {
      const row = data[index];
      if (topOI.includes(parseInt(row.OI))) $(this).find('td:eq(2)').addClass('oi-bold');      // OI
      if (topPEOI.includes(parseInt(row.PE_OI))) $(this).find('td:eq(8)').addClass('oi-bold');  // PE_OI
    });

    // Highlight ATM rows based on row.ATM
    $('#hocTable tbody tr').each(function (index) {
      const row = data[index];
      const atm = parseInt(row.ATM);
      if (!isNaN(atm)) {
        if (atm >= 0) $(this).find('td:lt(6)').addClass('atm-ce-style'); // First 6 CE cols
        if (atm <= 0) $(this).find('td:gt(5)').addClass('atm-pe-style'); // PE cols
      }
    });
  }, 10);
}


function clearCharts() {
  [oiChart, oiChangeChart, volumeChart, maxPainChart, totalOiChart, totalOiChangeChart].forEach(c => {
    if (c) c.destroy();
  });
}

function updateCharts(data) {
  const isMobile = window.innerWidth <= 767;

  const strikes = data.map(r => r.Strike);
  const spot = parseInt(data[0].Spot);
  const spotIndex = strikes.findIndex(s => parseInt(s) >= spot);
  const ceOi = data.map(r => parseInt(r.OI) || 0);
  const peOi = data.map(r => parseInt(r.PE_OI) || 0);
  const ceChange = data.map(r => parseInt(r.OI_Change) || 0);
  const peChange = data.map(r => parseInt(r.PE_OI_Change) || 0);
  const ceVol = data.map(r => parseInt(r.Volume) || 0);
  const peVol = data.map(r => parseInt(r.PE_Volume) || 0);
  const { ceOi: totalCeOi, ceOiChange: totalCeOiChange, peOi: totalPeOi, peOiChange: totalPeOiChange } = calculateFooterSums(data);
  clearCharts();

  const commonXAxis = {
  title: { display: true, text: 'Strike Price' },
  ticks: {
    font: { size: isMobile ? 8 : 12 },
    callback: function (val, index) {
      return isMobile && index % 2 !== 0 ? '' : this.getLabelForValue(val);
    },
    minRotation: isMobile ? 90 : 0,
    maxRotation: isMobile ? 90 : 0,
    align: isMobile ? 'start' : 'center'
  }
};


  const commonLegend = {
    labels: {
      font: { size: isMobile ? 10 : 12 }
    },
    position: 'top'
  };

  const yHidden = {
    display: !isMobile,
    title: { display: !isMobile, text: '' },
    ticks: { display: !isMobile },
    grid: { drawTicks: !isMobile }
  };

  oiChart = new Chart(document.getElementById("oiChart"), {
    type: "bar",
    data: {
      labels: strikes,
      datasets: [
        { label: "CE OI", data: ceOi, backgroundColor: "#40b0b2" },
        { label: "PE OI", data: peOi, backgroundColor: "#e76d67" }
      ]
    },
    options: {
      responsive: true,
      plugins: {
        legend: commonLegend,
        annotation: {
          annotations: {
            spotLine: {
              type: 'line',
              borderColor: 'black',
              borderWidth: 2,
              label: { content: 'Spot', enabled: true, position: 'start' },
              scaleID: 'x',
              value: spotIndex
            }
          }
        }
      },
      scales: {
        y: yHidden,
        x: commonXAxis
      }
    }
  });

  totalOiChart = new Chart(document.getElementById("totalOiChart"), {
  type: "bar",
  data: {
    labels: ["CE Total", "PE Total"],
    datasets: [{
      data: [totalCeOi, totalPeOi],
      backgroundColor: ["#40b0b2", "#e76d67"]
    }]
  },
  options: {
    plugins: {
      legend: { display: false }
    },
    scales: {
      y: {
        beginAtZero: true,
        title: { display: true, text: 'Total OI' },
        ticks: {
          callback: function (value) {
            if (value >= 1000000) return (value / 1000000).toFixed(1) + 'M';
            if (value >= 1000) return (value / 1000).toFixed(0) + 'k';
            return value;
          }
        }
      }
    }
  }
});


  oiChangeChart = new Chart(document.getElementById("oiChangeChart"), {
    type: "bar",
    data: {
      labels: strikes,
      datasets: [
        { label: "CE OI Change", data: ceChange, backgroundColor: "#40b0b2" },
        { label: "PE OI Change", data: peChange, backgroundColor: "#e76d67" }
      ]
    },
    options: {
      responsive: true,
      plugins: {
        legend: commonLegend,
        annotation: {
          annotations: {
            spotLine: {
              type: 'line',
              borderColor: 'black',
              borderWidth: 2,
              label: { content: 'Spot', enabled: true, position: 'start' },
              scaleID: 'x',
              value: spotIndex
            }
          }
        }
      },
      scales: {
        y: yHidden,
        x: commonXAxis
      }
    }
  });

  totalOiChangeChart = new Chart(document.getElementById("totalOiChangeChart"), {
  type: "bar",
  data: {
    labels: ["CE Change", "PE Change"],
    datasets: [{
      data: [totalCeOiChange, totalPeOiChange],
      backgroundColor: ["#40b0b2", "#e76d67"]
    }]
  },
  options: {
    plugins: {
      legend: { display: false }
    },
    scales: {
      y: {
        beginAtZero: true,
        title: { display: true, text: 'Total OI Change' },
        ticks: {
          callback: function (value) {
            if (value >= 1000000) return (value / 1000000).toFixed(1) + 'M';
            if (value >= 1000) return (value / 1000).toFixed(0) + 'k';
            return value;
          }
        }
      }
    }
  }
});


  volumeChart = new Chart(document.getElementById("volumeChart"), {
    type: "bar",
    data: {
      labels: strikes,
      datasets: [
        { label: "CE Volume", data: ceVol, backgroundColor: "#40b0b2" },
        { label: "PE Volume", data: peVol, backgroundColor: "#e76d67" }
      ]
    },
    options: {
      responsive: true,
      plugins: {
        legend: commonLegend
      },
      scales: {
        y: yHidden,
        x: commonXAxis
      }
    }
  });

  const lossArr = strikes.map((strike, i) => {
    let totalLoss = 0;
    for (let j = 0; j < strikes.length; j++) {
      const ceLoss = Math.max(0, strikes[j] - strike) * ceOi[j];
      const peLoss = Math.max(0, strike - strikes[j]) * peOi[j];
      totalLoss += ceLoss + peLoss;
    }
    return { strike, loss: totalLoss };
  });

  if (lossArr.length === 0) {
    document.getElementById("maxPainDisplay").innerText = `Max Pain: N/A`;
    return;
  }

  const lossData = lossArr.map(d => d.loss);
  const minLossObj = lossArr.reduce((min, curr) => curr.loss < min.loss ? curr : min);
  const maxPainColors = strikes.map(s => parseInt(s) <= spot ? '#40b0b2' : '#e76d67');

  maxPainChart = new Chart(document.getElementById("maxPainChart"), {
    type: "bar",
    data: {
      labels: strikes,
      datasets: [
        {
          label: "Total Loss (Max Pain)",
          data: lossData,
          backgroundColor: maxPainColors
        }
      ]
    },
    options: {
      responsive: true,
      plugins: {
        legend: commonLegend,
        tooltip: {
          callbacks: {
            label: ctx => `Loss: ₹${ctx.raw.toLocaleString()}`
          }
        }
      },
      scales: {
        y: yHidden,
        x: commonXAxis
      }
    }
  });

  document.getElementById("maxPainDisplay").innerText = `Max Pain: ${minLossObj.strike}`;
}

