function changeDate(newDate) {
  const dateDropdown = document.getElementById("exDate");
  dateDropdown.value = newDate;
  const event = new Event('change');
  dateDropdown.dispatchEvent(event);
}

// NEXT button
document.getElementById("nextDateBtn").addEventListener("click", () => {
  const current = document.getElementById("exDate").value;
  const idx = availableDates.indexOf(current);
  if (idx !== -1 && idx < availableDates.length - 1) {
    const nextDate = availableDates[idx + 1];
    changeDate(nextDate);
  }
});

// PREVIOUS button
document.getElementById("prevDateBtn").addEventListener("click", () => {
  const current = document.getElementById("exDate").value;
  const idx = availableDates.indexOf(current);
  if (idx > 0) {
    const prevDate = availableDates[idx - 1];
    changeDate(prevDate);
  }
});

