document.addEventListener("DOMContentLoaded", () => {
    const exyear = document.getElementById("exyear");
    const exmonth = document.getElementById("exmonth");
    const expiry = document.getElementById("expiry");
    const option = document.getElementById("option");
    const strike = document.getElementById("strike");

    // Keep a reference to the current chart and crosshair subscriber
    let priceChart = null;
    let crosshairUnsub = null;

    // Create a single tooltip element (once)
    const toolTip = document.createElement("div");
    toolTip.className = "floating-tooltip-2";
    toolTip.style.position = "absolute";
    toolTip.style.display = "none";
    toolTip.style.pointerEvents = "none";
    document.body.appendChild(toolTip);

    // --- 1️⃣ Load EX Year ---
    fetch("chart-files/option-chart.php?action=filters")
        .then(res => res.json())
        .then(data => {
            exyear.innerHTML = '<option value="">Select Year</option>' +
                               data.years.map(y => `<option value="${y}">${y}</option>`).join("");
        });

    // --- 2️⃣ EX Month ---
    exyear.addEventListener("change", () => {
        const year = exyear.value;
        if (!year) return;

        fetch(`chart-files/option-chart.php?action=months&year=${year}`)
            .then(res => res.json())
            .then(data => {
                exmonth.innerHTML = '<option value="">Select Month</option>' +
                                    data.months.map(m => `<option value="${m.value}">${m.name}</option>`).join("");
                expiry.innerHTML = '<option value="">Select Expiry</option>';
                strike.innerHTML = '<option value="">Select Strike</option>';
            });
    });

    // --- 3️⃣ Expiry ---
    exmonth.addEventListener("change", () => {
        const year = exyear.value;
        const month = exmonth.value;
        if (!year || !month) return;

        fetch(`chart-files/option-chart.php?action=expiries&year=${year}&month=${month}`)
            .then(res => res.json())
            .then(data => {
                expiry.innerHTML = '<option value="">Select Expiry</option>' +
                                   data.expiries.map(e => `<option value="${e}">${e}</option>`).join("");
                strike.innerHTML = '<option value="">Select Strike</option>';
            });
    });

    // --- 4️⃣ Option & Expiry trigger Strike load ---
    option.addEventListener("change", loadStrikes);
    expiry.addEventListener("change", loadStrikes);

    function loadStrikes() {
        const year = exyear.value;
        const month = exmonth.value;
        const exp = expiry.value;
        const opt = option.value;
        if (!year || !month || !exp || !opt) return;

        fetch(`chart-files/option-chart.php?action=strikes&year=${year}&month=${month}&expiry=${exp}&option=${opt}`)
            .then(res => res.json())
            .then(data => {
                strike.innerHTML = '<option value="">Select Strike</option>' +
                                    data.strikes.map(s => `<option value="${s}">${s}</option>`).join("");
            });
    }

    // --- Helper: Fix null OHLC by using previous close ---
    function fixNulls(data) {
        let prevClose = null;
        return data.map(c => {
            let candle = {
                time: +c.time,
                open: c.open !== null ? +c.open : null,
                high: c.high !== null ? +c.high : null,
                low:  c.low  !== null ? +c.low  : null,
                close:c.close!== null ? +c.close: null
            };

            if (candle.open === null || candle.high === null || candle.low === null || candle.close === null) {
